// src/components/ProjectPage.jsx
import React, { useState, useEffect, useRef } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import Editor from '@monaco-editor/react';
import '../css/Projectpage.css';

export default function ProjectPage() {
    const navigate = useNavigate();
    const { projectId } = useParams();

    const [renamingIndex, setRenamingIndex] = useState(null);
    const [menuOpenIndex, setMenuOpenIndex] = useState(null);
    const [projectName, setProjectName] = useState('');
    const [files, setFiles] = useState([]);
    const [activeIndex, setActiveIndex] = useState(0);
    const editorRef = useRef(null);
    const filePositionsRef = useRef({});
    const fileInputRef = useRef(null);

    // 프로젝트 이름 불러오기
    useEffect(() => {
        fetch(`http://localhost:4000/api/projects`, { credentials: 'include' })
            .then(res => res.json())
            .then(data => {
                if (data.success) {
                    const proj = data.projects.find(p => String(p.id) === projectId);
                    if (proj) setProjectName(proj.project_name);
                }
            })
            .catch(console.error);
    }, [projectId]);

    // 파일 목록 불러오기
    useEffect(() => {
        fetch(`http://localhost:4000/api/projects/${projectId}/files`, { credentials: 'include' })
            .then(res => res.json())
            .then(data => {
                if (data.success) {
                    setFiles(data.files.map(f => ({ name: f.name, content: f.content })));
                    setActiveIndex(0);
                }
            })
            .catch(console.error);
    }, [projectId]);

    // 커서 위치 복원
    useEffect(() => {
        if (!editorRef.current || files.length === 0) return;
        const pos = filePositionsRef.current[activeIndex] || { lineNumber: 1, column: 1 };
        editorRef.current.setPosition(pos);
        editorRef.current.revealPositionInCenter(pos);
    }, [activeIndex, files]);

    // 파일 내용을 서버에 저장
    const saveFileToServer = async ({ name, content }) => {
        try {
            const blob = new Blob([content], { type: 'text/plain' });
            const form = new FormData();
            form.append('file', blob, name);

            const res = await fetch('http://localhost:5000/upload', {
                method: 'POST',
                body: form,
            });
            const json = await res.json();
            console.log('업로드 결과:', json);
        } catch (err) {
            console.error('서버 저장 실패:', err);
        }
    };

    // 뒤로가기 (예: 메인으로)
    const handleBack = () => navigate(-1);

    // 프로젝트 이름 변경
    const handleRename = () => {
        const name = prompt('프로젝트 이름:', projectName);
        if (name) setProjectName(name.trim());
    };

    // 새 파일 생성
    const handleNewFile = () => {
        setFiles(prev => {
            const newFiles = [...prev, { name: '', content: '' }];
            const newIndex = newFiles.length - 1;
            setActiveIndex(newIndex);
            setRenamingIndex(newIndex);
            return newFiles;
        });
    };

    // 파일 클릭
    const handleFileClick = idx => {
        if (editorRef.current) {
            filePositionsRef.current[activeIndex] = editorRef.current.getPosition();
        }
        setActiveIndex(idx);
        setMenuOpenIndex(null);
    };

    // 에디터 마운트
    const handleEditorMount = editor => {
        editorRef.current = editor;
        editor.onDidChangeCursorPosition(e => {
            filePositionsRef.current[activeIndex] = e.position;
        });
    };

    // 코드 실행
    const run = () => {
        if (!editorRef.current) return;
        try {
            eval(editorRef.current.getValue());
        } catch (e) {
            console.error(e);
        }
    };

    return (
        <div className="replit-ide">
            <header className="replit-header">
                <div className="header-left">
                    <button className="icon-btn" onClick={handleBack}>🏠</button>
                    <span className="project-title" onClick={handleRename}>{projectName}</span>
                </div>
                <div className="header-right">
                    <button className="new-file" onClick={handleNewFile}>+ File</button>
                    <button className="run-btn" onClick={run}>▶ Run</button>
                </div>
            </header>
            <div className="replit-body">
                <aside className="file-explorer">
                    <div className="explorer-header">Files</div>
                    <div className="file-list">
                        {files.length === 0 ? (
                            <div className="empty-list">파일이 없습니다.</div>
                        ) : files.map((f, i) => (
                            <div key={i} className={`file-item ${activeIndex === i ? 'active' : ''}`}>
                                {renamingIndex === i ? (
                                    <input
                                        autoFocus
                                        value={f.name}
                                        onChange={e =>
                                            setFiles(prev =>
                                                prev.map((file, idx) =>
                                                    idx === i ? { ...file, name: e.target.value } : file
                                                )
                                            )
                                        }
                                        onBlur={e => {
                                            const newName = e.target.value.trim();
                                            setRenamingIndex(null);
                                            if (!newName) {
                                                // 빈 이름이면 삭제
                                                setFiles(prev => prev.filter((_, idx) => idx !== i));
                                                setActiveIndex(idx => (idx > 0 ? idx - 1 : 0));
                                            } else {
                                                // 이름 확정 → 서버 저장
                                                setFiles(prev => {
                                                    const next = prev.map((file, idx) =>
                                                        idx === i ? { ...file, name: newName } : file
                                                    );
                                                    saveFileToServer({ name: newName, content: next[i].content });
                                                    return next;
                                                });
                                            }
                                        }}
                                        onKeyDown={e => {
                                            if (e.key === 'Enter') e.target.blur();
                                        }}
                                        placeholder="파일 이름"
                                    />
                                ) : (
                                    <span
                                        className="file-label"
                                        onClick={() => handleFileClick(i)}
                                        onDoubleClick={() => setRenamingIndex(i)}
                                    >
                                        {f.name}
                                    </span>
                                )}
                                <div className="menu-container">
                                    <button
                                        className="menu-btn"
                                        onClick={() => setMenuOpenIndex(i === menuOpenIndex ? null : i)}
                                    >⋮</button>
                                    {menuOpenIndex === i && (
                                        <div className="menu-dropdown">
                                            <button onClick={() => { setRenamingIndex(i); setMenuOpenIndex(null); }}>이름 재설정</button>
                                            <button onClick={() => { setFiles(prev => prev.filter((_, idx) => idx !== i)); setActiveIndex(idx => (idx > 0 ? idx - 1 : 0)); setMenuOpenIndex(null); }}>삭제</button>
                                        </div>
                                    )}
                                </div>
                            </div>
                        ))}
                    </div>
                </aside>
                <section className="main-pane">
                    {files.length > 0 ? (
                        <>
                            <div className="editor-tabs">
                                <div className="tab active">{files[activeIndex]?.name}</div>
                            </div>
                            <Editor
                                height="calc(100% - 40px)"
                                theme="vs-dark"
                                language="c"
                                value={files[activeIndex].content}
                                onMount={handleEditorMount}
                                onChange={val =>
                                    setFiles(prev =>
                                        prev.map((file, idx) =>
                                            idx === activeIndex ? { ...file, content: val } : file
                                        )
                                    )
                                }
                                options={{ fontSize: 14 }}
                            />
                        </>
                    ) : (
                        <div className="empty-editor">새 파일을 추가하세요.</div>
                    )}
                </section>
            </div>
        </div>
    );
}
